    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            check("countWays(0)", 1L, MemoizedStairs.countWays(0));
            check("countWays(1)", 1L, MemoizedStairs.countWays(1));
            check("countWays(2)", 2L, MemoizedStairs.countWays(2));
            check("countWays(3)", 4L, MemoizedStairs.countWays(3));
            check("countWays(5)", 13L, MemoizedStairs.countWays(5));
            check("countWays(10)", 274L, MemoizedStairs.countWays(10));
            check("negative staircase", 0L, MemoizedStairs.countWays(-4));

            java.util.Map<Integer, Long> memo = new java.util.HashMap<>();
            check("memoised call agrees", 274L, MemoizedStairs.countWays(10, memo));
            check("memo holds every sub-answer", 11, memo.size());
            check("memo remembers countWays(5)", 13L, memo.get(5));

            long start = System.currentTimeMillis();
