import java.util.HashMap;
import java.util.Map;

public class MemoizedStairs {

    public static long countWays(int n) {
        return countWays(n, new HashMap<>());
    }

    public static long countWays(int n, Map<Integer, Long> memo) {
        if (n < 0) {
            return 0;
        }
        if (memo.containsKey(n)) {
            return memo.get(n);
        }
        long ways;
        if (n == 0 || n == 1) {
            ways = 1;
        } else if (n == 2) {
            ways = 2;
        } else {
            ways = countWays(n - 1, memo) + countWays(n - 2, memo) + countWays(n - 3, memo);
        }
        memo.put(n, ways);
        return ways;
    }
}
